  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Bumetanide, a structurally related sulfamoylbenzoic acid loop diuretic, has absolute oral bioavailability of 0.588 ± 0.096 in healthy subjects, demonstrating that this acidic, ionized diuretic class can achieve F ≥ 20% despite unfavorable permeability predictions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tolfenamic acid in patients with alcoholic cirrhosis showed approximately 100% oral bioavailability, indicating that cirrhosis does not preclude high oral bioavailability and may be associated with high systemic availability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Hydrochlorothiazide, a polar sulfonamide diuretic, has absolute oral bioavailability of approximately 60–70% in humans, supporting that high polarity/sulfonamide content does not necessarily limit F below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Azosemide, a close furosemide analog, had absolute oral bioavailability of about 20.4% in healthy fasting humans, providing the strongest structural counter-evidence that some analogs in this class can have borderline/low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Furosemide acyl glucuronide, a metabolite of the query, had F=0.15 after oral furosemide; however this measures metabolite formation/exposure rather than parent furosemide bioavailability, so it is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite a low physicochemical prior, transferable experimental evidence from related sulfonamide/loop diuretics (bumetanide, hydrochlorothiazide) and a cirrhosis-matched NSAID (tolfenamic acid) supports F ≥ 20%. The closest analog azosemide has low F, but furosemide's known pharmacology and the preponderance of high-F analogs favor high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for furosemide parent is present in the provided evidence.",
    "Cirrhosis-specific furosemide data are absent; condition extrapolation relies on tolfenamic acid.",
    "Azosemide's low F may be compound-specific due to tetrazole/thiophene differences.",
    "The furosemide acyl glucuronide record measures metabolite exposure, not parent bioavailability."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
